{"results": [{"id": "hp_doc_ed7f725415730405fb0c1296fb1f485a04b9447227c3f7a78b955c86b5f381cc", "title": "Torrens Island", "text": "Torrens Island is an island in the Australian state of South Australia located in the Port River Estuary between the Port River and Barker Inlet, about 15 km northwest of the state capital of Adelaide. Since European settlement of Adelaide in 1836, it has been used for a number of purposes.", "score": 23.8539}, {"id": "hp_doc_36c73661ebc6e3301e3b59679c9de33067cf7f6db85808bcbb63ae20295f1831", "title": "Torrens Island, South Australia", "text": "Torrens Island is a locality in the Australian state of South Australia located in the Adelaide metropolitan area within the estuary of the Port River about 16 km north-west of the Adelaide city centre.", "score": 22.8719}, {"id": "hp_doc_736c44b0e986963f17f08096dcb920a7075021f22486d497ea195e4b788c2ab3", "title": "Torrens Island Concentration Camp", "text": "The Torrens Island Internment Camp was a World War I concentration camp, located on Torrens Island in the Port River Estuary near Adelaide in South Australia. The camp opened on 9 October 1914 and held up to 400 men of German or Austro-Hungarian background, or crew members of enemy ships who had been caught in Australian ports at the beginning of the war. They were held without trial under the provisions of the \"War Precautions Act 1914\".", "score": 21.388}], "remaining_searches": 2}
